import React, { useState } from "react";
import "./App.css";
import axios from "axios";

function App() {
  const [formData, setFormData] = useState({
    hs_avg: "",
    first_term_gpa: "",
    math_score: "",
    english_grade: ""
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await axios.post(
        "http://localhost:5000/predict", // backend URL
        {
          hs_avg: Number(formData.hs_avg),
          first_term_gpa: Number(formData.first_term_gpa),
          math_score: Number(formData.math_score),
          english_grade: Number(formData.english_grade)
        }
      );

      setResult(response.data);
    } catch (error) {
      console.error(error);
      alert("Backend not connected yet!");
    }

    setLoading(false);
  };

  return (
    <div className="container">
      <h1>🎓 Student Success Dashboard</h1>

      <form onSubmit={handleSubmit} className="form">
        <input name="hs_avg" placeholder="High School Average" onChange={handleChange} />
        <input name="first_term_gpa" placeholder="First Term GPA" onChange={handleChange} />
        <input name="math_score" placeholder="Math Score" onChange={handleChange} />
        <input name="english_grade" placeholder="English Grade" onChange={handleChange} />

        <button type="submit">
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div className="results">
          <h2>📊 Results</h2>
          <p>Completion: {result.completion === 1 ? "Yes" : "No"}</p>
          <p>Persistence: {result.persistence === 1 ? "Yes" : "No"}</p>
          <p>Predicted GPA: {result.gpa}</p>
          <p>Performance: {result.performance}</p>
        </div>
      )}
    </div>
  );
}

export default App;









